#include "guardrails.hpp"
#include "test_support.hpp"
using namespace g9;static ActionDescriptor a(RiskClass r,std::string k="k"){ActionDescriptor x;x.risk=r;x.equivalence_key=std::move(k);return x;}int main(){Guardrails b(GuardrailProfile::balanced);CHECK(b.decide(a(RiskClass::read)).action==PolicyAction::allow);CHECK(b.decide(a(RiskClass::filesystem_destructive)).action==PolicyAction::ask);CHECK(b.decide(a(RiskClass::vcs_destructive)).action==PolicyAction::deny);b.allow_for_session("d");CHECK(b.decide(a(RiskClass::filesystem_destructive,"d")).action==PolicyAction::allow);Guardrails r(GuardrailProfile::review);CHECK(r.decide(a(RiskClass::write)).action==PolicyAction::ask);return test_support::finish();}
